-- Populate wiki article: ALE-DSGN-013-03 Spatial Quality — Scale, Proportion, and Enclosure
-- Updates article content, sources, and EI prompt.

-- Ensure wiki_article_sources table exists (may not be in schema file yet)
CREATE TABLE IF NOT EXISTS public.wiki_article_sources (
  source_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id  UUID NOT NULL REFERENCES public.wiki_articles(article_id) ON DELETE CASCADE,
  label       TEXT NOT NULL,
  description TEXT,
  url         TEXT,
  source_type TEXT NOT NULL DEFAULT 'reference_standard',
  sort_order  SMALLINT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

DO $$
DECLARE
  v_article_id uuid;
BEGIN

  UPDATE public.wiki_articles SET
    title            = 'Spatial Quality — Scale, Proportion, and Enclosure',
    subject_label    = 'ALE-DSGN-013 · Anthropometrics & Human Dimensions',
    difficulty_label = 'Intermediate',
    ale_tests_you    = 'Evaluate spatial enclosure using D/H ratios, apply classical proportion systems (golden section, √2 rectangle) to room and facade design, determine ceiling heights per PD 1096, and analyze how scale, proportion, and enclosure affect human spatial perception.',
    updated_note     = 'Updated March 21, 2026',
    status           = 'published',
    content          = E'Space is not a container. It is an experience.\n\nWhen you walk into a great building, something happens before you read a single detail. The ceiling soars or presses close. The room opens wide or holds you in. A corridor pulls you forward or makes you hesitate. These effects are not accidental. They are the result of deliberate decisions about scale, proportion, and enclosure — the three fundamental levers of spatial quality.\n\nThe ALE tests whether you can predict how a space will feel from its dimensions alone. Given a street section with building heights and widths, can you evaluate the quality of that outdoor room? Given a room plan, can you assess whether its proportions are harmonious or awkward? Given a ceiling height, can you determine whether it meets code and whether it serves the intended use? This article builds the analytical framework to answer all three questions.\n\n<KeyValues items={[{value: "1:1.618", label: "golden ratio (φ)"}, {value: "2.70 m", label: "min ceiling (PD 1096)"}, {value: "D/H = 1", label: "threshold of enclosure"}, {value: "1,200 mm", label: "social zone start"}]} />\n\n---\n\n## Scale: the human body as measure\n\n<WikiCalloutBox type="most-tested">\n**Scale is not size.** A 3-meter ceiling feels intimate in a Gothic cathedral but grand in a bedroom. Scale is always relative — relative to the human body, to the expected use of the space, and to the surrounding context. A space that is "correct" in absolute dimensions can feel wrong at the wrong scale.\n</WikiCalloutBox>\n\nArchitectural scale operates at three levels simultaneously. **Human scale** refers to the relationship between the space and the standing, moving, reaching body — doorways at 2,100 mm, counters at 850–900 mm, handrails at 865–965 mm. **Interior scale** refers to the relationship between room dimensions and their expected occupancy — a 3.0 m ceiling reads differently in a living room than in a lobby. **Urban scale** refers to the relationship between building heights, street widths, and the body moving through a city.\n\nThe most common scale error in exam questions is confusing absolute size with perceived scale. A cathedral nave 40 meters tall is not "out of scale" — it is monumental scale, which is exactly appropriate. A bedroom with a 6-meter ceiling is out of scale because the human activities of sleeping and dressing do not require or justify that vertical dimension. Scale is always purposeful.\n\n| Ceiling height | Psychological effect | Appropriate use |\n|----------------|---------------------|------------------|\n| 2.40 m (minimum upper floor) | Contained, intimate, focused | Small bedrooms, bathrooms, service areas |\n| 2.70 m (minimum ground floor) | Neutral, residential normal | Standard residential rooms, small offices |\n| 3.00 – 3.60 m | Comfortable, slightly elevated | Living rooms, dining rooms, standard commercial |\n| 3.60 – 4.50 m | Spacious, civic, important | Lobbies, conference rooms, retail |\n| 4.50 – 6.00 m | Monumental, awe-inspiring | Grand halls, museums, religious buildings |\n| Above 6.00 m | Sublime, potentially overwhelming | Cathedrals, major civic buildings, atria |\n\n**PD 1096 ceiling height requirements (§805):**\n\n| Floor | Minimum clear height | Notes |\n|-------|---------------------|-------|\n| Ground floor (habitable rooms) | 2.70 m | Measured from finished floor to lowest obstruction |\n| Upper floors (habitable rooms) | 2.40 m | Same measurement basis |\n| Mezzanine floor | 1.80 m | Minimum from floor to ceiling underside |\n| Garages | 2.00 m | Vehicle clearance |\n| Basements | 2.40 m | If used as habitable space |\n\n<WikiCalloutBox type="ale-watch">\nPD 1096 §805 measures ceiling height from **finished floor level to the lowest point of the ceiling or any obstruction**, including beams, ducts, and dropped ceilings. A room with a 2.70 m slab-to-slab height but a 300 mm deep beam fails the 2.40 m requirement if the beam drops the clear height to 2.40 m exactly — you need to measure to the underside of the beam, not the slab above.\n</WikiCalloutBox>\n\n---\n\n## Proportion: the geometry of harmony\n\nProportion is the mathematical relationship between dimensions. Where scale asks "how big relative to the body," proportion asks "how do the dimensions of this space relate to each other?" A room that is 3 m × 3 m × 3 m has perfect proportion (cube) but no directionality. A room that is 3 m × 10 m × 3 m has extreme proportion — corridorlike, with a strong dominant axis.\n\nThe classical tradition identified specific proportional ratios that produce what trained eyes perceive as visual harmony. These are not arbitrary cultural preferences. Several correspond to geometric relationships (the diagonal of a square, the Fibonacci sequence) that recur throughout natural forms and have been used since antiquity.\n\n<ProportionComparator />\n\n### The golden section (φ = 1 : 1.618)\n\nThe golden section is the ratio where the smaller dimension relates to the larger as the larger relates to the whole: if a : b, then a/b = b/(a+b). Numerically this converges to φ ≈ 1.618. The Greeks used it in the Parthenon façade; Renaissance architects codified it as the primary proportional tool for rooms, windows, and façades.\n\nIn practice, the golden rectangle is used for:\n- Room plans: a living room 5.0 m × 8.1 m is approximately golden (ratio = 1.62)\n- Window openings: a 1,200 mm wide window with 740 mm height is golden\n- Façade bays: the width-to-height of a façade bay or pilaster spacing\n- Urban blocks: the proportion of a city block or courtyard plan\n\n<FormulaBlock label="Golden Section Derivation" steps={[{variable: "φ", operator: "=", operands: ["(1 + √5)", "2"], symbol: "÷"}, {variable: "φ", operator: "=", operands: ["1.6180339..."], symbol: ""}, {variable: "a/b", operator: "=", operands: ["b/(a+b)"], symbol: ""}, {variable: "", operator: "", operands: ["Fibonacci series: 1, 1, 2, 3, 5, 8, 13, 21... → ratios converge to φ"], comment: ""}]} />\n\n### The √2 rectangle (1 : 1.414)\n\nThe √2 rectangle is derived from the diagonal of a unit square. It has the unique property that when folded in half across the long axis, the resulting rectangle has the same proportions (√2 : 1). This is why A-series paper works: an A4 sheet folded is two A5 sheets, both with the same proportions.\n\nIn architecture, √2 appears in:\n- Traditional Japanese tatami rooms (the 2:3 mat grid approximates √2)\n- ISO 216 paper sizes (the entire A, B, C series)\n- Medieval floor plans derived from the *ad quadratum* method\n- Many contemporary Japanese residential spaces\n\n### Root rectangles (√3, √4, √5)\n\nThe root rectangle family extends the √2 system. Each is constructed geometrically from the previous:\n\n| Rectangle | Ratio | Construction | Use |\n|-----------|-------|-------------|-----|\n| √2 | 1 : 1.414 | Diagonal of unit square | A-series paper, Japanese tatami |\n| √3 | 1 : 1.732 | Diagonal of √2 rectangle | Medieval architecture, Vesica Piscis |\n| √4 | 1 : 2.000 | Double square | Corridors, dining rooms, formal halls |\n| √5 | 1 : 2.236 | Diagonal of double square | Related to φ: √5 – 1 / 2 = 0.618 |\n\n### The Modulor (Le Corbusier, 1948)\n\nLe Corbusier developed the Modulor as a universal proportional system based on the human body at 1,830 mm (6 feet) tall. He derived two arithmetic series:\n\n- **Red series** (based on navel height): 113, 70, 43, 27, 16... mm\n- **Blue series** (based on raised hand): 226, 140, 86, 53, 33... mm\n\nThe Modulor was applied throughout the Unité d''Habitation (Marseille, 1952) — ceiling heights, door heights, window positions, and kitchen dimensions all derive from these series. Critics argue it privileges a specific body type; defenders argue its internal consistency creates visual harmony even if the absolute values are not universal.\n\n<Tip title="Design Principle">\nProportion systems are tools for **decision-making under constraint**, not magic formulas. A room proportioned to the golden section in plan is not automatically beautiful. What proportion systems do is eliminate arbitrary decisions — if you commit to √2, you have a principled basis for every dimension. The result is spatial consistency, which the eye reads as harmony.\n</Tip>\n\n---\n\n## Enclosure: the D/H ratio\n\nEnclosure is the degree to which a space feels bounded, contained, or "held." In exterior space — streets, courtyards, plazas, urban rooms — enclosure is primarily controlled by the ratio of distance (D) to wall height (H). This is the D/H ratio, codified by the Japanese architect Yoshinobu Ashihara in *Exterior Design in Architecture* (1970).\n\n<DHRatioExplorer />\n\nThe D/H ratio is a ratio of horizontal to vertical dimension. D is the distance between opposing enclosing surfaces (building faces, walls, hedges). H is the height of those surfaces.\n\n| D/H ratio | Spatial quality | Design implication |\n|-----------|----------------|--------------------|\n| < 0.5 | Oppressive, claustrophobic | Avoid in occupied exterior space; acceptable in narrow passages for effect |\n| 0.5 – 1.0 | Enclosed, intimate | Traditional alley, Japanese machiya street, Gothic quarter |\n| 1.0 | Threshold of enclosure | The critical value — walls and sky feel equally present |\n| 1.0 – 2.0 | Well-defined, comfortable | Most successful urban streets, traditional piazzas |\n| 2.0 | "Sweet spot" — comfortable and spacious | Grand boulevard scale, campus quads, many historic civic spaces |\n| 2.0 – 3.0 | Open, enclosure weakening | Suburban arterials, enclosure still perceptible |\n| > 3.0 | Enclosure dissolves | Buildings read as objects; landscape elements needed for coherence |\n| > 4.0 | Spatially lost | Highway scale, big-box retail pads, no spatial definition |\n\n<WikiCalloutBox type="most-tested">\nThe ALE may give you building heights and street widths and ask you to evaluate the quality of the outdoor room. Always divide D ÷ H: **if D/H < 1, the space is enclosed; if D/H = 1, it is at the threshold; if D/H > 3, enclosure has dissolved.** The question may not use the term "D/H ratio" — it may simply give you dimensions and ask whether the street feels "intimate," "comfortable," "open," or "lost."\n</WikiCalloutBox>\n\n**Ashihara''s external space framework** extends beyond the ratio. He distinguished between *positive space* (space with enclosure and identity, like a plaza or courtyard) and *negative space* (leftover space between objects, without enclosure or identity). His key insight: the D/H ratio is necessary but not sufficient. A space also needs a consistent enclosing plane (buildings of similar height), a defined edge (not dissolving into open landscape), and a clear interior focus (fountain, monument, or tree) to achieve spatial identity.\n\nUrban rooms also require a **scale reference** at the human level. A street that achieves the right D/H at building scale can still feel inhospitable if the ground-floor treatment has no human-scale detail — blank walls, no entries, no rhythm of openings. The 3–5 meter zone experienced by a pedestrian at eye level must have detail at body scale even if the overall D/H is correct.\n\n---\n\n## Ceiling height and vertical proportion\n\nIn interior space, vertical proportion operates differently from urban scale. The critical relationship is between plan area and ceiling height — a small room with a very high ceiling feels bizarre (a compression of horizontal scale against vertical expansion), while a large room with a low ceiling feels oppressive.\n\nA practical rule from residential practice: ceiling height should be approximately **1/4 to 1/5 of the room''s longest plan dimension** for rooms under 12 meters. A 6 m × 9 m living room reads well with a 2.70–3.00 m ceiling (longest dimension 9 m ÷ 3.0 m ceiling = 3.0, within range). A 3 m × 3 m bedroom with a 3.60 m ceiling will feel oddly vertical.\n\n<Tabs>\n<Tab label="PD 1096 Requirements" value="pd1096">\n\nThe 2004 Revised IRR of PD 1096 establishes statutory minimums. These are floors — good design targets are always higher.\n\n| Space type | Minimum clear height | Code reference |\n|------------|---------------------|---------------|\n| Habitable rooms — ground floor | 2.70 m | §805 |\n| Habitable rooms — upper floors | 2.40 m | §805 |\n| Mezzanine floors | 1.80 m | §805 |\n| Garages | 2.00 m | §805 |\n| Basements (habitable) | 2.40 m | §805 |\n| Corridors and passages | 2.40 m | §1207 |\n\n**Measurement basis:** Finished floor level (FFL) to the lowest obstruction (ceiling surface, beam underside, duct, or other permanent obstruction).\n\n**Key exam trap:** The 2.70 m minimum applies to the **ground floor only**. Upper floors drop to 2.40 m. A multi-storey residential building does not need 2.70 m on every floor.\n\n</Tab>\n<Tab label="Psychological Effects" value="psychology">\n\nResearch in environmental psychology establishes consistent patterns in how ceiling height affects cognition and behavior:\n\n| Ceiling height | Cognitive effect | Behavioral tendency |\n|----------------|-----------------|--------------------|\n| < 2.40 m | Focused, convergent thinking | Task concentration, reduced wandering |\n| 2.40 – 2.70 m | Neutral, slightly enclosed | Efficient work, comfortable sleep |\n| 2.70 – 3.00 m | Normal, unrestricted | Balanced between focus and creativity |\n| 3.00 – 4.50 m | Open, expansive thinking | Abstract thinking, social interaction, creativity |\n| > 4.50 m | Awe, diminished self | Reverence, submissiveness, sensory openness |\n\nThe landmark study by Meyers-Levy and Zhu (2007) demonstrated that subjects in high-ceilinged rooms performed better on tasks requiring abstract, integrative thinking, while subjects in low-ceilinged rooms performed better on detail-focused tasks. This has direct implications for library reading rooms (high for browsing, lower alcoves for study), open-plan offices, and residential design.\n\n</Tab>\n<Tab label="Design Guidelines" value="guidelines">\n\nPractical guidance for matching ceiling height to program:\n\n**Raise the ceiling when:**\n- The room has a public or civic function (lobbies, entry halls, reception areas)\n- The program requires social interaction over sustained periods (dining rooms, living rooms)\n- Natural light is the primary light source (higher ceiling = more sky exposure from windows)\n- The room is large in plan (high ceiling balances large floor plate)\n- The architect wants to signal importance or arrival\n\n**Lower the ceiling when:**\n- The room has a focused, task-oriented program (home office, bedroom, kitchen)\n- Acoustic intimacy is desired (dining alcove, music practice room, reading nook)\n- Energy performance is a priority (less volume = less conditioning load)\n- Creating a shelter-within-a-shelter effect (inglenook, booth seating, reading alcove under a mezzanine)\n\n**Vary the ceiling within a space when:**\n- Articulating zones within an open plan (higher over social area, lower over workstation)\n- Creating prospect-refuge sequences (lower at entry, higher at view terminus)\n- Using the ceiling plane as a spatial generator (raking, vaulting, coffering)\n\n</Tab>\n</Tabs>\n\n---\n\n## Proxemic zones and spatial behavior\n\nEdward T. Hall coined the term *proxemics* in *The Hidden Dimension* (1966) to describe the invisible spatial bubbles humans maintain around their bodies. Hall identified four distance zones derived from field observation of North American middle-class subjects. These zones have direct design applications because spaces must accommodate interactions at each zone without forcing inappropriate proximity.\n\n| Zone | Distance range | Sensory characteristics | Architectural design application |\n|------|---------------|------------------------|----------------------------------|\n| Intimate | 0 – 450 mm | Touch, breath, body heat | Bathroom, sleeping area, medical examination. Spaces should provide for necessary intimate contact while maintaining privacy from others |\n| Personal | 450 – 1,200 mm | Clear facial features, low voice, scent | Desk and workstation layouts, pair seating, consultation rooms. Minimum between facing workstations: 1,200 mm |\n| Social | 1,200 – 3,600 mm | Full body visible, normal voice, impersonal contact | Conference tables, reception counters, interview rooms. Standard office desk-to-visitor distance falls here |\n| Public | 3,600 mm+ | Body shrinks in visual field, formal voice | Lecture halls, stages, ceremonial spaces. Speaker-to-audience minimum distance for formal address |\n\nHall''s zones describe comfort thresholds. Design fails when spaces force interactions at the wrong zone: a narrow two-seat consultation room that places strangers at intimate distance, or a conference table so wide (> 3,600 mm) that the far end falls in public-distance territory, making conversation effortful.\n\n**Cross-cultural note:** Hall''s research was conducted primarily with North American and Northern European subjects. Mediterranean, Middle Eastern, and Southeast Asian cultures typically use smaller distance zones — the same table width reads as normal in one cultural context and as cold or formal in another. Philippine residential practice tends toward closer social distances than North American norms.\n\n<Tip title="Design Principle">\n**Furniture placement creates implied proxemic boundaries.** A sofa and two chairs arranged around a coffee table define a social-distance zone regardless of the room size around them. The furniture cluster becomes a "room within a room." The architect''s job is to size the overall space so the furniture cluster sits comfortably within it, with enough residual space for circulation but not so much that the cluster feels lost.\n</Tip>\n\n---\n\n## Prospect-refuge theory\n\nJay Appleton proposed *prospect-refuge theory* in *The Experience of Landscape* (1975). His central argument: humans evolved in environments where survival depended on two contradictory needs — the ability to **see** (prospect, to detect danger and opportunity) and the ability to **hide** (refuge, to be protected from predators and weather). Aesthetic preference in landscape and space reflects the residue of these evolutionary pressures.\n\nA space with high prospect-refuge balance satisfies both: you can see far while your back is protected. This is why:\n- Corner tables in restaurants fill first\n- Window seats are premium\n- Living room furniture clusters face toward entries and views, not away\n- Alcoves and inglenooks feel cozy rather than claustrophobic (refuge without enclosure)\n- Elevated platforms feel prestigious (prospect advantage)\n- Open-plan offices with no back protection generate stress (all prospect, no refuge)\n\n**Application to interior design:**\n\nIn **restaurant seating**, prospect-refuge explains the hierarchy: booths with high backs (refuge) facing the room entrance (prospect) are most coveted; central exposed tables with no back protection are least preferred. Successful restaurant layouts resolve this by varying booth depth, using banquettes against walls, and positioning the primary axis of tables to face the entry sequence.\n\nIn **office layouts**, the open-plan trend has generated measurable productivity and wellbeing problems partly because it eliminates refuge. Partial-height panels (1,200–1,500 mm), strategic planting, acoustic ceiling treatments, and "heads-down" alcoves restore refuge within an overall open plan without reverting to closed private offices.\n\nIn **residential living rooms**, the default furniture arrangement should place primary seating with backs toward walls (refuge) and sightlines toward the entry and any exterior view (prospect). A sofa floating in the center of a large room with no wall behind it violates prospect-refuge — occupants report feeling uncomfortable without knowing why.\n\n---\n\n## Common mistakes\n\n<WikiMistakeList mistakes={[{number: 1, title: "Confusing scale with size", wrongValue: "A 10-meter-wide room is large-scale", correctValue: "Scale is relative to the body and the use — a 10 m room can be grand, domestic, or overwhelming depending on ceiling height and program", explanation: "Scale has no absolute meaning. A space is only large-scale or small-scale in relation to the human body and the expected activity. The ALE tests relational thinking, not absolute dimension memorization."}, {number: 2, title: "Applying the golden ratio without understanding why", wrongValue: "All rooms should be 1:1.618", correctValue: "The golden section is one of several valid proportion systems; the choice depends on the spatial character desired and the construction system", explanation: "The golden section is not a universal rule. A square room (1:1) is appropriate for certain uses. A double-square (1:2) works well for dining rooms and galleries. Use proportion systems as decision tools, not commandments."}, {number: 3, title: "Ignoring D/H ratio in site planning", wrongValue: "Building heights and setbacks are only structural and regulatory concerns", correctValue: "D/H ratio determines the spatial quality of the outdoor room — it must be evaluated as part of site design", explanation: "Every setback decision creates a D/H ratio. A 10 m setback against a 10 m building = D/H 1 (enclosed and defined). A 30 m setback against the same building = D/H 3 (enclosure dissolving). Site planners must evaluate spatial quality, not just regulatory compliance."}, {number: 4, title: "Setting all ceilings to minimum code height", wrongValue: "All rooms: 2.70 m ground floor, 2.40 m upper floors", correctValue: "Code minimums are regulatory floors. Good design varies ceiling heights to match program, scale, and spatial sequence", explanation: "A building where every room has the minimum legal ceiling height is spatially monotonous and often fails to serve its program. Lobbies, living rooms, and primary spaces benefit from ceiling heights well above code minimum. Bedrooms and service spaces may be appropriate at minimum height."}, {number: 5, title: "Placing furniture that violates proxemic expectations", wrongValue: "Centering furniture symmetrically in a large room for visual balance", correctValue: "Clustering furniture to create social-distance zones with backs toward walls (refuge) and views toward entries (prospect)", explanation: "A sofa centered in a 10 m × 10 m room may look balanced on plan but feel uncomfortable to occupy. Furniture should create defined social-distance zones (1,200–3,600 mm between conversation seats) with prospect-refuge orientation, regardless of the larger room geometry around it."}]} />\n\n---\n\n## Spatial quality drill\n\n<SpatialQualityDrill />\n\n---\n\n## Check yourself\n\n<InlineQuiz question="A 20-meter wide street is lined with 10-meter tall buildings on both sides. What is the D/H ratio and how would the street feel?" options={[{text: "D/H = 2 — comfortable, spacious but spatially defined", is_correct: true}, {text: "D/H = 0.5 — tightly enclosed, potentially claustrophobic", is_correct: false}, {text: "D/H = 2 — enclosure has dissolved, the street feels lost", is_correct: false}, {text: "D/H = 10 — the buildings are too short relative to the street width", is_correct: false}]} rationale="D/H = 20 ÷ 10 = 2.0. This places the street in the comfortable-spacious zone — well-defined by Ashihara''s framework. The sky is a significant presence, but the buildings are close enough that you feel enclosed within an outdoor room rather than between isolated objects. This is the scale of many successful European grand boulevards." />\n\n<InlineQuiz question="What is the golden section ratio and where is it most commonly applied in architecture?" options={[{text: "1:1.618 — applied to facade proportions, room plans, window openings, and courtyard dimensions", is_correct: true}, {text: "1:1.414 — the √2 rectangle, used in A-series paper and Japanese tatami rooms", is_correct: false}, {text: "1:1.618 — used only for structural column spacing", is_correct: false}, {text: "1:2 — the double square, basis of all classical room proportions", is_correct: false}]} rationale="The golden section φ = 1:1.618 is derived from the relationship where a/b = b/(a+b). It is applied to room plan proportions (e.g., 5 m × 8.1 m ≈ golden), facade bays, window openings (width:height), and courtyard plans. The √2 rectangle (1:1.414) is a separate system associated with A-series paper and tatami." />\n\n<InlineQuiz question="PD 1096 requires a minimum ceiling height of ___ on the ground floor and ___ on upper floors for habitable rooms." options={[{text: "2.70 m ground floor; 2.40 m upper floors", is_correct: true}, {text: "2.40 m ground floor; 2.10 m upper floors", is_correct: false}, {text: "3.00 m ground floor; 2.70 m upper floors", is_correct: false}, {text: "2.70 m on all floors", is_correct: false}]} rationale="PD 1096 §805 sets 2.70 m for habitable rooms on the ground floor and 2.40 m on upper floors. A common exam error is applying 2.70 m to all floors — the upper floor reduction to 2.40 m is a deliberate statutory distinction." />\n'
  WHERE slug = 'ale-dsgn-013-03'
  RETURNING article_id INTO v_article_id;

  IF v_article_id IS NULL THEN
    RAISE EXCEPTION 'No wiki_articles row found with slug = ale-dsgn-013-03';
  END IF;

  -- ── Sources ──────────────────────────────────────────────────
  DELETE FROM public.wiki_article_sources WHERE article_id = v_article_id;

  INSERT INTO public.wiki_article_sources (article_id, label, description, url, source_type, sort_order) VALUES
    (v_article_id, 'Francis D.K. Ching', 'Architecture: Form, Space, and Order, 4th Edition — spatial organization, proportion systems, and enclosure principles', NULL, 'reference_standard', 1),
    (v_article_id, 'Yoshinobu Ashihara', 'Exterior Design in Architecture (1970) — D/H ratio theory and the framework of positive vs. negative exterior space', NULL, 'reference_standard', 2),
    (v_article_id, 'Jay Appleton', 'The Experience of Landscape (1975) — prospect-refuge theory and its application to spatial preference', NULL, 'reference_standard', 3),
    (v_article_id, 'Edward T. Hall', 'The Hidden Dimension (1966) — proxemic distance zones: intimate, personal, social, and public', NULL, 'reference_standard', 4),
    (v_article_id, 'PD 1096 — 2004 Revised IRR', '§805 ceiling height minimums for ground floors (2.70 m) and upper floors (2.40 m), mezzanines, and garages', NULL, 'implementing_rules', 5),
    (v_article_id, 'Le Corbusier', 'The Modulor (1948) — proportional system based on the human body at 1,830 mm; red and blue series; applied throughout Unité d''Habitation', NULL, 'reference_standard', 6);

  -- ── EI Prompt ─────────────────────────────────────────────────
  INSERT INTO public.wiki_ei_prompts (
    article_id,
    prompt_text,
    reveal_text,
    insert_after_heading,
    options,
    sort_order,
    is_active,
    status
  ) VALUES (
    v_article_id,
    'An architect designs an outdoor courtyard that is 30 meters × 30 meters, surrounded by 5-story buildings that are 15 meters tall. What is the D/H ratio and how would this courtyard feel?',
    'D/H = 30 ÷ 15 = 2.0. This is the comfortable zone — the courtyard would feel spacious but spatially defined. The buildings are close enough to create a clear sense of enclosure (you feel "in" a space, not between isolated objects) but far enough apart that the sky becomes a significant presence. This is the scale of many successful European piazzas such as the Campo in Siena and Piazza della Repubblica in Florence. If the buildings were only 3 stories (approximately 10 m), D/H would rise to 3.0 — the enclosure would weaken significantly and the courtyard would begin to feel like an open lot rather than an outdoor room.',
    'Enclosure: the D/H ratio',
    '[
      {"text": "D/H = 2.0 — comfortable, spacious but spatially defined", "is_correct": true},
      {"text": "D/H = 0.5 — tightly enclosed, potentially claustrophobic", "is_correct": false},
      {"text": "D/H = 6.0 — no sense of enclosure, space feels lost", "is_correct": false},
      {"text": "D/H = 1.0 — threshold of enclosure, perfectly balanced", "is_correct": false}
    ]'::jsonb,
    0,
    true,
    'published'
  );

END $$;
